  const codebuddySummary = isCodebuddyFamilyProvider(provider)
    ? summarizeCodebuddyAuth(provider, credentialRecord && credentialRecord.nativeAuth)
    : null;
  // zcode 的桌面会话过期是**凭据事实**，不是运行时错误：access_token 是带 exp 的
